    $('q-measure-stars').disabled=!!busy||!state.starIds.size;$('q-selection-count').textContent=state.selected.size+' маркирани кадъра';if($('q-ai-worst')){const count=allScoped().filter(r=>window.AstroArchiveQualityPlot.warningKinds(r).ai).length;$('q-ai-worst').disabled=!!busy||!count;$('q-ai-worst').textContent='Според AI ('+count+')';}
